    tasks = _collect_coder_tasks(workplan)
    _check_task_file_paths(tasks, violations)
    return violations


def _resolve_workplan(plan) -> object:
    """Extract the workplan from a plan or its strategy."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return workplan


def _collect_coder_tasks(workplan) -> list[object]:
    """Gather all coder tasks from workplan groups."""
    tasks: list[object] = []
    for group in getattr(workplan, 'groups', []) or []:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _check_task_file_paths(tasks: list[object], violations: list[str]) -> None:
    """Validate each task has exactly 1 file_path and no duplicates across tasks."""
    seen: set[str] = set()
    for task in tasks:
        fps = getattr(task, 'file_paths', None) or []
        if len(fps) != 1:
            violations.append(
                f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)"
            )
        for fp in fps:
            if fp in seen:
                violations.append(f'file collision: {fp} in multiple tasks')
            seen.add(fp)"}

